            Method sizeB = b.getClass().getMethod("size");
            int n = (Integer) sizeA.invoke(a);
            if (n != (Integer) sizeB.invoke(b)) return false;
            Method getA = a.getClass().getMethod("get", int.class);
            Method getB = b.getClass().getMethod("get", int.class);
